  export const InvoiceLabelsPdf1X3 = async (list) => {
    
   //console.log(list)

    const pdfDoc = await PDFDocument.create() 
    pdfDoc.registerFontkit(fontkit);
  
   
  
    const fonstP = await initializeFonts(pdfDoc);
  
    
    // 1" = 72
  
  
    let Qr40Dimz = {
      x: 2,
      y: 35,
      width:  35,
      height: 35,
    }
  
  
    const promises = list.map(async (item, ind2) => {
        const page = pdfDoc.addPage([187, 72]);
        const { width, height } = page.getSize();
        let heightPg = height - 19;
        let xxL = width;


        const pngUrl = getQrcode(item?.invoiceId+"");
        const pngImageBytes = await fetch(pngUrl).then((res) => res.arrayBuffer())
        let pngImage = await pdfDoc.embedPng(pngImageBytes);
        pngImage && page.drawImage(pngImage, Qr40Dimz)
  
        
    
      const invoiceWidth = fonstP.GSansBold.widthOfTextAtSize(item?.document+"" , 18);
    
      page.drawText( item?.document + "", {
        x: xxL - 6 - invoiceWidth,
        y:  heightPg-6,
        size: 18,
        font: fonstP.GSansBold,
        color:  rgb(0, 0, 0),
      })
    

      let sellerNm = item?.clientName ? item?.clientName + "" : "";
  
  
      // const sellerWidth = fonstP.GSansBold.widthOfTextAtSize(sellerNm , 9);
    
      
      
      heightPg = heightPg -25;
      
      

      page.drawText( sellerNm, {
        x: 5,
        y:  heightPg -19,
        size: 9,
        font: fonstP.GSansBold,
        color:  rgb(0, 0, 0),
      })
    

      let productName = getStore("providers_ids")?.[item?.customer?.providerId]?.name;
        
      //console.log(productName)


      page.drawText(productName + "", {
          x: 6,
          y:  heightPg -6 ,
          size: 10,
          font: fonstP.GSansBold,
          color: rgb(0, 0, 0),
        })
      
      
    })
    const contents = await Promise.all(promises);
  
  
  
    const pdfBytes = await pdfDoc.save();
    let blobUrl = blobfromArray(pdfBytes)
    window.open(blobUrl)
  
    
    
    }
    
  
  
  






