import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, ObjectKeys, hasWritePrivilege, parseDateMMDDYYYY, AccountYears, qryStore, fetchEncryptStream } from "../../../stores/Utils";

import "./dashboard.css"

import { OpenModal } from "../../../components/DialogHRM";
import { getall_deposit, sortDeposits, delete_deposit } from "../services/server_fetching";
import { ContainerElasticView, SvgIcon_Cmpt } from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";
import { DepositSummary2Pdf } from "../services/export_service";
import { DepositManualView } from "..";
import { useNavigate } from "react-router";



const Svg = SvgIcon_Cmpt();

const frmNm = "new_multi_deposit_prov";


const DepositItem  = ({ data, index, handleRefreshAll, show, viewFee }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const navigate = useNavigate();



	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())
		}
	});

	if(!show){
		return null;
	}
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}



	const refreshAccs =  () => {
		getall_deposit(updObs)
	}

	const update = async () => {
		
	}

	
	


	const openSubMayor =  (sba) => {
		if(!data?.comprobanteId){
			updStore(frmNm, data);
			updStore(frmNm+"_bck", JSON.parse(JSON.stringify(data)));
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			modaldata["content"] =  <DepositManualView confirm={refreshAccs} item={data}/>
			OpenModal(modaldata);
		}else{
			//rmvComp()
			navigate({
				pathname: "/accounting-ledger" ,
				search: `?cId=${data.comprobanteId}`
			});
		}
	}


	const deleteComprobante =  () => {
		//delete_deposit(data?.depositSummaryId, handleRefreshAll);
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert confirm={deleteComprobante} item={data} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	const printDeposit = () => {
		DepositSummary2Pdf(data);
		
	}

	const rmvComp = async ()=>{
	
		let bdyq2 = {...getStore(qryStore())?.upd_deposit_summary};
		bdyq2.params = {
			businessId: getStore("profileUser")?.businessId,
			depositSummaryId: data?.depositSummaryId
		}
		bdyq2.data2update = {comprobanteId: 0 };	
		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		
		if (td && !td.error) {
			getall_deposit(updObs)
		}
	}
		

	
	let subAcc = sortDeposits( getStore("sub_deposit_group")?.[data.depositId],"subDeposit");
	
	


	

	const selectAll = () => {
		let depositFeeSelected = getStore("depositFeeSelected") || {};
		if(depositFeeSelected?.[data.id]){
			delete depositFeeSelected[data.id];
		}else{
			depositFeeSelected[data.id] = data.paymentDepositFee*-1;
		}
		updStore("depositFeeSelected", depositFeeSelected);
		updObs()
	}

	if(data?.transactions.length===0){
		return null
	}


	let depositFeeSelected = getStore("depositFeeSelected")?.[data.id]

	return (
		<div className={` ${index} deposit_box `} deposit-id={`${data.id}`} >
			<div className="_dsplFlx ">	
				{viewFee && data?.comprobanteId?
				<div className="align_itm">
					
					<div className="icon align_itm" onClick={selectAll}>
						<Svg name={depositFeeSelected?"check_circle_outline":"radio_unchecked"} color={depositFeeSelected?"var(--hrm_palette-blue-purple)":"var(--hrm_palette-imput-label_gray)"}/>
					</div>
					
				</div>
				 :null}
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance "></div>
					<div className="value_deposit_gross">
					{parseDateMMDDYYYY(data?.depositDate)} 
					</div>
				</div>
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					<div className="icon_image " style={{padding:"5px 10px 0 0"}} onClick={printDeposit}>
						<Svg name={"printer"} color={" var(--hrm_palette-blue-purple)"}/>
					</div>
					
					<div className="icon_image " style={{padding:"5px 10px 0 0"}} onClick={openSubMayor}>
						<Svg name={data?.comprobanteId?"success":"google-spreadsheet"} color={data?.comprobanteId?"var(--hrm_palette-success-fg)":"var(--partial-success)"}/>
					</div>

				</div>
			</div>

			<div className="_dsplFlx ">
				<div>
					
					<div className="_dsplFlx ">
						<div  className="key_deposit_balance ">
						Deposit ID:
						</div>
						<div  className="value_deposit_balance ">
						{data?.id}
						</div>
					</div>
					<div className="_dsplFlx ">
						<div className="trnsNo">
						{data?.transactions.length}
						</div>
						
						<div  className=" _dsplFlx value_deposit_balance ">
						 {data?.transactions.length>1?"transactions":"transaction"}
						</div>
					</div>
				</div>
			
				<div className="flexSpace"/>
			
				<div>
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance " style={{width: 130}} />
					<div className="value_deposit_gross">
						${(data?.amount*1).toFixed(2)}
					</div>
				</div>
				
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance "style={{width: 130}}>
					Fees:
					</div>
					<div  className="value_deposit_balance ">
					${(data?.paymentDepositFee*1).toFixed(2)}
					 </div>
				</div>
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance " style={{width: 130}}>
					Net amount:
					</div>
					<div  className="value_deposit_balance ">
					 ${(data?.amount*1 - data?.paymentDepositFee*1).toFixed(2)}
					 </div>
				</div>
				</div>
				
			</div>
			<ContainerElasticView >
				<div className=" spaceAround flxWrp "  style={{margin: "6px 0 6px"}} >
					{data?.transactions?.map(trItm=>{
						
						return (
							<TransactionItem  data={trItm} id={trItm.id}  />
						)
					})}
				</div>
			</ContainerElasticView>
		</div>
	)
}
export default DepositItem;








const TransactionItem  = ({ data, index, handleRefreshAll, show }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);


	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
		}
	});

	
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	



	let cleanName = data?.contactName?.split('/\n')?.join("");

	
	return (
		<div className={` ${index} deposit_boxItm `} >
			
			<div className="_dsplFlx ">
				<div>
					<div className="_dsplFlx ">
						<div  className="key_deposit_balance "></div>
						<div className="value_deposit_gross">
						{data?.processorTransactionReference} 
						</div>
					</div>
					<div className="_dsplFlx ">
						<div  className="key_deposit_balance ">
						Documeto Referencia:
						</div>
						<div  className="value_deposit_name ">
						{data?.referenceNumber} 
						</div>
					</div>
					<div className="_dsplFlx ">
						<div  className="key_deposit_balance ">
						Customer:
						</div>
						<div  className="value_deposit_name ">
						{cleanName} 
						</div>
					</div>
				</div>
			
				<div className="flexSpace"/>
			
				<div>
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance " style={{width: 130}} />
					<div className="value_deposit_gross">
						${(data?.amount*1).toFixed(2)}
					</div>
				</div>
				
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance "style={{width: 130}}>
					Fees:
					</div>
					<div  className="value_deposit_balance ">
					${(data?.totalTransactionFee*1).toFixed(2)}
					 </div>
				</div>
				<div className="_dsplFlx ">
					<div  className="key_deposit_balance " style={{width: 130}}>
					Net amount:
					</div>
					<div  className="value_deposit_balance ">
					 ${(data?.amount*1 - data?.totalTransactionFee*1).toFixed(2)}
					 </div>
				</div>
				</div>
				
			</div>
		</div>
	)
}